"""Full-text appraisal, batch 28 (2026-11-20, Brendan signed in to CKN).
EBSCO through CKN's LibKey links: fujii-2005 (Karger), dukarm-2005 (Liebert).
Free copies found today: tsang-2023 (journal site), erbay-2022 (open access at Ovid, DOI found),
mira-2024 (HAL author copy), ferrao-2003 (SciELO; the letter sits on the issue's letters page),
bagnati-2013 (the full 2021 report in an open-access journal), stuve-2003 (Tijdschrift voor Psychiatrie archive).
Conference abstracts read in Embase through CKN (abstract = full publication): zakrzewski-2013, sandeep-2013.
Excluded: stuve-2003, E3 (lamotrigine was stopped to treat the psychosis; also E4, remission once a probable cause was removed).
Also: sair-2018 timeline gains the exposure_stop its authors describe (oedema resolving before the relapse).
"""
import sys
sys.path.insert(0, "scripts")
from lib_code import Batch, ev, track, T, A, J, N, H  # noqa: E402

b = Batch("2026-11-20", source="Full text through CKN (EBSCO, Embase) or a free copy")

# sair-2018: add the exposure_stop the authors describe, so the timeline carries the natural off-on
s = b.by_id["sair-2018"]
evs = s["timeline"][0]["events"]
if not any(e["kind"] == "exposure_stop" for e in evs):
    evs.insert(len(evs) - 1, ev("exposure_stop", 6, "weeks", "Haematoma and oedema resolving, compression of the striatum easing (MRI)", "approx"))

